Given a sorted and rotated array arr[] of distinct elements, find the index of given key in the array. If the key is not present in the array, return -1. Examples:  Input: arr[] = [5, 6, 7, 8, 9, 10, 1, 2, 3], key = 3Output: 8Explanation: 3 is present at index 8.Input: arr[] = [3, 5, 1, 2], key = 6Output: -1Explanation: 6 is not present.Input: arr[] = [33, 42, 72, 99], key = 42Output: 1Explanation: 42 is found at index 1.Try It YourselfTable of Content[Naive Approach] Using Linear Search - O(n) Time and O(1) Space[Expected Approach 1] Using Binary Search Twice - O(log n) Time and O(1) Space[Expected Approach 2] Using Single Binary Search - O(log n) Time and O(1) Space[Naive Approach] Using Linear Search - O(n) Time and O(1) SpaceA simple approach is to iterate through the array and check for each element, if it matches the target then return the index, otherwise return -1. To know more about the implementation, please refer Introduction to Linear Search Algorithm.
            C++

    #include <iostream>
#include <vector>
using namespace std;

int search(vector<int>& arr, int key) {
    for (int i = 0; i < arr.size(); i++) {
        // Check each element one by one
        if (arr[i] == key)
            return i;
    }
    // Key not found
    return -1;
}

int main() {
    vector<int> arr = {5, 6, 7, 8, 9, 10, 1, 2, 3};
    int key = 3 ;

    int index = search(arr, key) ;
    cout << index << endl ; 

    return 0 ;
}


